-- 0001 bootstrap — Factory Bridge Global
-- Scope (ADR-019, docs/MIGRATION_DEPENDENCY_MAP.md §2): objects with NO dependency on business tables.
--   * extensions
--   * schema `app` and its privilege defaults
--   * generated enums (single source of truth: packages/domain/src/enums.ts; block regenerated by
--     `pnpm db:gen-enums` and drift-tested in supabase/tests/migrations.test.ts)
--   * app.current_user_id()
-- Nothing here reads memberships/organizations; those helpers live in 0002 (after their tables).

-- Extensions -----------------------------------------------------------------
-- btree_gist: required for EXCLUDE constraints mixing uuid equality with numrange overlap (quote_tiers, 0009).
create extension if not exists btree_gist;

-- Schema ---------------------------------------------------------------------
create schema if not exists app;

-- Default privileges: functions in `app` are NOT executable by public/anon unless granted explicitly.
revoke all on schema app from public;
grant usage on schema app to authenticated, service_role;
alter default privileges in schema app revoke execute on functions from public;

-- Enums (generated) ----------------------------------------------------------
-- BEGIN GENERATED ENUMS (packages/domain/src/enums.ts) — do not edit by hand
create type public.check_type as enum ('business_license_reviewed', 'uscc_matched', 'address_corroborated', 'video_call_held', 'factory_visit', 'export_license_seen', 'bank_name_matches_entity', 'reference_checked');
create type public.compliance_state as enum ('clear', 'review_required', 'blocked');
create type public.cost_line_status as enum ('sourced', 'estimated', 'missing', 'not_applicable');
create type public.document_status as enum ('uploaded', 'scanning', 'rejected', 'parsed', 'extracted', 'in_review', 'accepted', 'discarded');
create type public.member_role as enum ('owner', 'admin', 'member', 'viewer', 'operator', 'compliance_reviewer', 'platform_admin');
create type public.org_type as enum ('buyer', 'supplier', 'internal');
create type public.price_basis as enum ('EXW', 'FCA', 'FOB', 'CFR', 'CIF', 'DAP', 'DPU', 'DDP', 'unknown');
create type public.quote_status as enum ('confirmed', 'superseded', 'expired', 'withdrawn');
create type public.quote_type as enum ('listing', 'supplier_catalog', 'negotiated_private', 'final_offer', 'estimate');
create type public.review_status as enum ('pending', 'in_review', 'accepted', 'rejected');
create type public.rights_class as enum ('internal_market_observation', 'catalog_public_with_permission', 'customer_private_quote', 'buyer_uploaded_private', 'supplier_submitted_private');
create type public.source_type as enum ('manual_research', 'operator_import', 'buyer_upload', 'supplier_portal', 'supplier_csv_feed', 'inbound_email', 'supplier_api', 'marketplace_api');
create type public.supplier_stage as enum ('lead_identified', 'contact_confirmed', 'legal_identity_reviewed', 'capabilities_documented');
create type public.visibility_scope as enum ('internal_only', 'owning_org', 'named_orgs', 'platform_buyers');
-- END GENERATED ENUMS

-- Helpers with no table dependencies ----------------------------------------
-- auth.uid() is provided by Supabase (reads the verified JWT). The local test harness shims it.
create or replace function app.current_user_id()
returns uuid
language sql
stable
set search_path = ''
as $$
  select auth.uid();
$$;

revoke execute on function app.current_user_id() from public;
grant execute on function app.current_user_id() to authenticated, service_role;

comment on schema app is 'Factory Bridge Global: authorization helpers, trusted writers and lifecycle functions. See docs/MIGRATION_DEPENDENCY_MAP.md.';
comment on function app.current_user_id() is 'Subject of every authorization decision; never parameterised.';
